{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C129", "C130", "C150", "C162", "C167", "C61", "C49", "C46"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C129", "C130", "C150", "C162", "C167", "C61", "C49", "C46"],
  "claims": [
    {
      "claim": "L4 records for sulfonylurea analogs show high intestinal absorption: glipizide is highly permeable with FA >95% (C129), glimepiride is almost completely absorbed after oral dosing (C130), and Caco-2 Papp values are ~10×10^-6 cm/s for glipizide (C150, C162) and 18.1×10^-6 cm/s for glibenclamide (C167). This supports that the query's sulfonyl semicarbazide chemotype can be well absorbed despite acidic ionization.",
      "card_ids": ["C129", "C130", "C150", "C162", "C167"]
    },
    {
      "claim": "Prior human absolute-bioavailability contexts remain supportive: zolpidem ~68-70% (C61), solifenacin 88% (C49), and quinapril ~50% (C46); none of these transferable human values falls below 20%.",
      "card_ids": ["C61", "C49", "C46"]
    },
    {
      "claim": "L3 oral-exposure records for sulfonylurea/sulfonamide analogs (tolbutamide AUC, glibenclamide AUC, torsemide Cmax, indapamide AUC/Cmax) show measurable systemic exposure after oral dosing, supporting absorption in the query's chemotype.",
      "card_ids": ["C89", "C96", "C113", "C101", "C80", "C104", "C94", "C114", "C116", "C99", "C102", "C100", "C106", "C88"]
    },
    {
      "claim": "L4 solubility/dissolution records are mostly formulation-specific (SNEDDS, solid dispersions, lipid excipients) for glimepiride, celecoxib, and sulpiride; they do not provide intrinsic absorption or F evidence and are not contradictory.",
      "card_ids": ["C149", "C136", "C159", "C163", "C174", "C170", "C157"]
    },
    {
      "claim": "No L4 record provides affirmative evidence for F<20%; the query's low logD/high TPSA prior is mitigated by the high permeability of analogous sulfonylureas at similar ionization states.",
      "card_ids": ["C129", "C130", "C167"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C129", "C130", "C150", "C162", "C167"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule.",
    "L4 records are for sulfonylurea analogs, not the query; the semicarbazide vs urea difference may alter permeability or metabolism.",
    "No human PK, dose, formulation, or route data for the query.",
    "First-pass metabolism and systemic clearance for the query are unmeasured.",
    "The query's low neutral fraction and logD remain physicochemical concerns, not endpoint proof."
  ],
  "decision_summary": "L4 intestinal absorption and permeability records for sulfonylurea analogs (glipizide FA >95%, glimepiride almost complete absorption, high Caco-2 Papp for glipizide/glibenclamide) support absorption in the query's chemotype and mitigate the physicochemical prior; no affirmative evidence indicates F<20%, so F>=20% remains better supported."
}

